// Save per-language report mirroring ExportDesignModel behavior.
var reportsDir = Path.Combine("..", "..", "reports", "model-kpi");
Directory.CreateDirectory(reportsDir);
var reportPath = Path.Combine(reportsDir, "net.json");
var report = new
{
    aspect_ratio_xy = insights.AspectRatioXY,
    aspect_ratio_xz = insights.AspectRatioXZ,
    aspect_ratio_yz = insights.AspectRatioYZ,
    bounding_box_max = insights.BoundingBoxMax,
    bounding_box_min = insights.BoundingBoxMin,
    centroid = insights.Centroid,
    characteristic_length = insights.CharacteristicLength,
    convex_hull_volume = insights.ConvexHullVolume,
    dimension_x = insights.DimensionX,
    dimension_y = insights.DimensionY,
    dimension_z = insights.DimensionZ,
    euler_characteristic = insights.EulerCharacteristic,
    face_count = insights.FaceCount,
    footprint_area = insights.FootprintArea,
    is_watertight = insights.IsWatertight,
    moments_of_inertia = insights.MomentsOfInertia,
    principal_axes = insights.PrincipalAxes,
    slenderness = insights.Slenderness,
    total_surface_area = insights.TotalSurfaceArea,
    vertex_count = insights.VertexCount,
};
var json = JsonConvert.SerializeObject(report, Formatting.Indented);
File.WriteAllText(reportPath, json);

// Load canonical asset and require exact match.
var canonicalPath = Path.Combine(AssetsPath, "model-kpi-nakagin.json");
